/// 获取 Rys 多项式求积的根和权重（插值法）
pub fn rys_roots(n: usize, alp: f64) -> Vec<[f64; 2]> {
    let alps = RYS_ALPS.to_vec();
    let (roots, weits) = match n {
        1 => (RYS_ROOTS_1.to_vec(), RYS_WEITS_1.to_vec()),
        2 => (RYS_ROOTS_2.to_vec(), RYS_WEITS_2.to_vec()),
        3 => (RYS_ROOTS_3.to_vec(), RYS_WEITS_3.to_vec()),
        4 => (RYS_ROOTS_4.to_vec(), RYS_WEITS_4.to_vec()),
        5 => (RYS_ROOTS_5.to_vec(), RYS_WEITS_5.to_vec()),
        _ => panic!("rys_roots: n not supported"),
    };
    (0..n)
        .map(|i| {
            let root = maths::lag_intpol(&alps, &roots[i].to_vec(), alp);
            let weit = maths::lag_intpol(&alps, &weits[i].to_vec(), alp);
            [root, weit]
        })
        .collect()
}

